escenas.animacion:
const W=A.W;
const tNo=A.k('no',1.0), tGu=A.k('guarda',1.333), tCo=A.k('contraseña…',2.0), tCm=A.k('¿cómo',2.333);
const tNu=A.k('nueva',3.667), tIg=A.k('igual',4.333), tAn=A.k('anterior?',5.333);
const acc=A.accent||'#FFD400', red='#FF3B5C', ink='#cfe3ff';
A.bg('#0b1630','#050a18');

// ventana del navegador
const pb=A.p(0,0.6,'snapSettle');
A.with(()=>{
  A.rect(140,440,800,660,{r:28,fill:'#0f1d3d',stroke:ink,lw:4});
  A.line([[140,515],[940,515]],{stroke:ink,lw:3,alpha:0.7});
  A.circle(185,478,10,{fill:red});A.circle(220,478,10,{fill:acc});A.circle(255,478,10,{fill:'#4cd98a'});
  A.rect(330,458,420,40,{r:20,fill:'#0a1530',stroke:'rgba(207,227,255,0.4)',lw:2});
  A.text('pagina.com',540,480,{size:28,color:'#8fb0e0',weight:700,align:'center'});
},{x:540,y:770,scale:A.lerp(0.85,1,pb),alpha:pb});

// base de datos
const pm=A.p(tCm,0.7,'glide');
const pDb=A.p(0.35,0.5,'softLand');
const dbY=A.lerp(930,1010,pm), dbS=A.lerp(1,0.65,pm);
function db(cx,cy,s){
  const w=260*s,h=150*s,e=34*s;
  ctx.save();ctx.lineWidth=4;ctx.strokeStyle=ink;ctx.fillStyle='#13264f';
  ctx.beginPath();ctx.moveTo(cx-w/2,cy-h/2);ctx.lineTo(cx-w/2,cy+h/2);
  ctx.ellipse(cx,cy+h/2,w/2,e,0,Math.PI,0,true);ctx.lineTo(cx+w/2,cy-h/2);ctx.closePath();ctx.fill();ctx.stroke();
  ctx.restore();
  try{A.lib.hatch(ctx,[[cx-w/2,cy-h/2],[cx+w/2,cy-h/2],[cx+w/2,cy+h/2],[cx-w/2,cy+h/2]],{angle:45,spacing:14,width:1.5,color:'rgba(207,227,255,0.22)'});}catch(err){}
  ctx.save();ctx.lineWidth=4;ctx.strokeStyle=ink;
  ctx.beginPath();ctx.ellipse(cx,cy,w/2,e,0,Math.PI,0,true);ctx.stroke();
  ctx.fillStyle='#1d3a72';ctx.beginPath();ctx.ellipse(cx,cy-h/2,w/2,e,0,0,Math.PI*2);ctx.fill();ctx.stroke();
  ctx.restore();
}
const sh=(t>tCo&&t<tCo+0.35)?14*(1-(t-tCo)/0.35):0;
A.with(()=>{
  db(540,dbY,dbS);
  const xs=A.pop(tCo,0.45);
  if(t>=tCo){
    const r=70*dbS*xs;
    A.line([[540-r,dbY-r],[540+r,dbY+r]],{stroke:red,lw:16,glow:20});
    A.line([[540+r,dbY-r],[540-r,dbY+r]],{stroke:red,lw:16,glow:20});
  }
},{x:540,y:dbY,alpha:pDb*pb,shake:sh});
const pNo=A.p(tCo,0.4,'popOver');
A.label('NO SE GUARDA',540,1070,{size:34,bg:red,color:'#fff',scale:pNo,alpha:pNo*(1-pm)});
A.flash(tCo,0.2,0.25);

// cápsula de la contraseña
const pw='gato2024';
const nCh=Math.floor(A.clamp((t-0.3)/0.6)*pw.length);
const pf=A.p(tGu,0.6,'gentleIn'), pbk=A.p(tCo,0.5,'popOver');
let cy=620+190*pf-170*pbk; cy=A.lerp(cy,720,pm);
const cx=A.lerp(540,330,pm), cw=A.lerp(420,280,pm);
const pIn=A.pop(0.2,0.45);
const glowNu=t>tNu?(0.6+0.4*Math.sin((t-tNu)*8)):0;
A.with(()=>{
  A.rect(cx-cw/2,cy-48,cw,96,{r:48,fill:'#0a1530',stroke:t>tNu?acc:ink,lw:5,glow:glowNu*25});
  let s=pw.slice(0,nCh); if(t<tGu&&Math.floor(t*3)%2===0) s+='|';
  A.text(s,cx,cy,{size:46,color:'#fff',weight:800,align:'center'});
},{x:cx,y:cy,scale:pIn});
const pLN=A.pop(tNu,0.45);
if(t>=tNu) A.label('NUEVA',330,620,{size:38,bg:acc,color:'#0b1630',scale:pLN});

// gran pregunta
if(t>=tCm){
  A.rings(540,720,tCm,{count:3,speed:500,gap:0.2,maxR:380,color:acc,lw:4,alpha:0.5});
  const pq=A.pop(tCm,0.5), pI=A.p(tIg,0.6,'glide');
  const qs=A.lerp(240,90,pI)*pq, qy=A.lerp(720,640,pI)+Math.sin(t*5)*6*(pI);
  A.with(()=>A.text('?',540,qy,{size:qs,color:acc,weight:900,align:'center',stroke:'#0b1630',strokeWidth:8}),{x:540,y:qy,rot:Math.sin(t*3)*0.06});
  if(t>=tIg){
    const pe=A.p(tIg+0.1,0.4,'softLand');
    A.line([[505,705],[575,705]],{stroke:'#fff',lw:12,progress:pe});
    A.line([[505,735],[575,735]],{stroke:'#fff',lw:12,progress:pe});
  }
}

// cápsula fantasma: la anterior, que no existe
if(t>=tIg){
  const pr=A.p(tIg,0.7,'whip');
  const gx=A.lerp(540,750,pr), gy=A.lerp(dbY,720,pr);
  const isAn=t>=tAn;
  const gsh=(t>tAn&&t<tAn+0.4)?12*(1-(t-tAn)/0.4):0;
  const col=isAn?red:'rgba(207,227,255,0.8)';
  A.with(()=>{
    const x0=gx-140,x1=gx+140,y0=gy-48,y1=gy+48;
    A.line([[x0+48,y0],[x1-48,y0],[x1,gy],[x1-48,y1],[x0+48,y1],[x0,gy],[x0+48,y0]],{stroke:col,lw:5,dash:[18,12]});
    A.text('? ? ?',gx,gy,{size:46,color:col,weight:900,align:'center',alpha:0.5+0.5*Math.abs(Math.sin(t*4))});
  },{x:gx,y:gy,alpha:pr,scale:A.lerp(0.4,1,pr),shake:gsh});
  if(isAn) A.label('ANTERIOR',750,620,{size:38,bg:red,color:'#fff',scale:A.pop(tAn,0.45)});
}

const W=A.W, ac=A.accent, red='#FF5A6E', white='#FFFFFF', dark='#05202a', steel='#8fb3c9';
A.bg('#0a1626','#050b14');
const tPag=A.k('páginas',0.333), tNo=A.k('no',1.0), tG=A.k('Guardan',2.333), tH=A.k('huella',3.0), tUn=A.k('un',3.333), tC=A.k('código',3.667), tHash=A.k('hash',4.333);
const cx=540;
const MONO='bold 52px "JetBrains Mono","Fira Mono","Courier New",monospace';
// ---------- tiempos de la contraseña ----------
const pw='gato12';
const tI=tNo+0.32;               // impacto contra el servidor
const dropP=A.p(tNo,0.32,'gentleIn');
const backP=A.p(tI+0.1,0.55,'snapSettle');
const restY=560, hitY=1530;
const tDraw=tI+0.63;             // empieza a dibujarse la huella (~1.95s)
const drawP=A.p(tDraw,0.45,'softLand');
const mP=A.p(tDraw+0.5,0.45,'softInOut'); // cápsula entra en la huella
const fpx=cx, fpy=820;
// ---------- SERVIDOR (abajo) ----------
const vx=cx, vy=1690;
const vs=A.pop(tPag,0.5);
const impactShake=(t>tI&&t<tI+0.4)?16*(1-(t-tI)/0.4):0;
const stored=A.p(tHash+0.3,0.3,'snapSettle');
if(vs>0){
  A.with(()=>{
    const on=stored>0;
    A.rect(vx-280,vy-80,560,160,{r:26,fill:'#0f2236',stroke:on?ac:steel,lw:6,glow:on?28*stored:0});
    A.lib.hatch(ctx,[[vx-270,vy-70],[vx+270,vy-70],[vx+270,vy+70],[vx-270,vy+70]],{angle:-0.6,spacing:22,width:1.5,color:'rgba(143,179,201,0.16)'});
    // candado
    ctx.save();ctx.strokeStyle=steel;ctx.lineWidth=7;ctx.lineCap='round';
    ctx.beginPath();ctx.arc(vx-190,vy-12,24,Math.PI,0);ctx.lineTo(vx-166,vy+4);ctx.moveTo(vx-214,vy-12);ctx.lineTo(vx-214,vy+4);ctx.stroke();ctx.restore();
    A.rect(vx-224,vy+2,68,52,{r:10,fill:steel});
    A.text('SERVIDOR',vx+50,vy-22,{size:40,color:steel,weight:'800',align:'center'});
    A.rect(vx-110,vy+12,320,20,{r:8,fill:on?ac:'#1d3a52',alpha:on?A.lerp(0.4,1,stored):1});
    A.rect(vx-110,vy+44,220,20,{r:8,fill:'#1d3a52'});
  },{x:vx,y:vy,scale:vs,shake:impactShake});
}
// ---------- RECHAZO ----------
A.flash(tI,0.18,0.3);
if(t>tI){
  const xs=A.pop(tI,0.4);
  const xa=1-A.p(tG-0.2,0.35,'softInOut');
  if(xa>0){
    A.with(()=>{
      A.line([[cx-60,1390],[cx+60,1510]],{stroke:red,lw:20});
      A.line([[cx+60,1390],[cx-60,1510]],{stroke:red,lw:20});
    },{x:cx,y:1450,scale:xs,alpha:xa});
    A.label('NO SE GUARDA',cx,1560,{size:44,bg:red,color:white,scale:A.pop(tI+0.1,0.4),alpha:xa});
    A.rings(cx,vy-80,tI,{count:2,speed:520,gap:0.1,maxR:260,color:red,lw:5,alpha:0.6*xa});
  }
}
// ---------- HUELLA ----------
if(drawP>0){
  const rnd=A.rand(7);
  const glowB=t>tH?22:8;
  const pulse=t>tUn?1+0.04*Math.sin((t-tUn)*14):1;
  A.with(()=>{
    ctx.save();ctx.lineCap='round';ctx.strokeStyle=ac;ctx.shadowColor=ac;ctx.shadowBlur=glowB;ctx.lineWidth=8;
    for(let i=0;i<9;i++){
      const rx=16+i*14, ry=rx*1.3;
      const pi=A.clamp(drawP*1.5-i*0.055);
      const s=Math.PI*(0.95+rnd()*0.15), span=Math.PI*(1.1+rnd()*0.8);
      if(pi<=0) continue;
      ctx.beginPath();ctx.ellipse(fpx,fpy+i*3,rx,ry,0,s,s+span*pi);ctx.stroke();
      if(i>2&&i%2===1){const s2=s+span+0.35;ctx.beginPath();ctx.ellipse(fpx,fpy+i*3,rx,ry,0,s2,s2+Math.PI*0.5*pi);ctx.stroke();}
    }
    ctx.restore();
  },{x:fpx,y:fpy,scale:pulse});
}
if(t>tH){
  A.rings(fpx,fpy,tH,{count:3,speed:420,gap:0.18,maxR:300,color:ac,lw:4,alpha:0.55});
  A.label('HUELLA',cx,575,{size:56,bg:ac,color:dark,scale:A.pop(tH,0.45)});
}
// ---------- CÁPSULA CONTRASEÑA ----------
let py=t<tI+0.1?A.lerp(restY,hitY,dropP):A.lerp(hitY,restY,backP);
py=A.lerp(py,fpy,mP);
const squash=(t>tI&&t<tI+0.25)?1-0.12*Math.sin((t-tI)/0.25*Math.PI):1;
const pillS=A.pop(0,0.45)*A.lerp(1,0.25,mP);
const pillA=1-A.clamp((mP-0.3)/0.7);
const nChars=Math.floor(A.clamp(t/0.6)*pw.length);
const isRed=t>tI&&t<tDraw+0.1;
if(pillA>0.01&&pillS>0){
  A.with(()=>{
    A.with(()=>{
      A.rect(cx-240,py-70,480,140,{r:70,fill:'#13283d',stroke:isRed?red:white,lw:6,glow:isRed?18:0});
      ctx.save();ctx.strokeStyle=ac;ctx.lineWidth=6;ctx.beginPath();ctx.arc(cx-165,py-6,18,Math.PI,0);ctx.stroke();ctx.restore();
      A.rect(cx-187,py-8,44,36,{r:7,fill:ac});
      const cursor=(Math.floor(t*3)%2===0)?'|':'';
      A.text(pw.slice(0,nChars)+(nChars<pw.length?cursor:''),cx+35,py+22,{size:68,color:white,weight:'800',align:'center'});
      if(isRed){
        const sp=A.p(tI,0.25,'crashIn');
        A.line([[cx-75,py+2],[cx-75+220*sp,py+2]],{stroke:red,lw:9});
      }
    },{x:cx,y:py,scale:1,alpha:1});
  },{x:cx,y:py,scale:pillS,alpha:pillA});
  ctx.save();
  ctx.restore();
  if(squash!==1){}
}
// ---------- HAZ: HUELLA -> HASH ----------
const hexs='0123456789ABCDEF';
if(t>tUn&&t<tHash+0.4){
  const fade=1-A.p(tHash,0.35,'softInOut');
  A.line([[cx,990],[cx,1350]],{stroke:ac,lw:4,alpha:0.35*fade,dash:[14,14],progress:A.p(tUn,0.4,'glide')});
  A.particles(44,11,(i,rnd)=>{
    const birth=tUn+i*0.02, life=0.55;
    const p=(t-birth)/life;
    if(p<0||p>1) return;
    const e=p*p*(3-2*p);
    const off=(rnd()-0.5)*220;
    const x=cx+off*(1-e)+(rnd()-0.5)*600*e*0.9;
    const y=A.lerp(990,1430+(rnd()-0.5)*80,e);
    const a=Math.sin(p*Math.PI)*fade;
    if(i%3===0){
      ctx.save();ctx.globalAlpha=a;ctx.font='bold 34px "JetBrains Mono","Courier New",monospace';ctx.textAlign='center';
      ctx.fillStyle=ac;ctx.shadowColor=ac;ctx.shadowBlur=14;ctx.fillText(hexs[Math.floor(rnd()*16)],x,y);ctx.restore();
    } else {
      A.circle(x,y,5+rnd()*4,{fill:ac,alpha:a,glow:12});
    }
  });
}
// ---------- CAJA DEL HASH ----------
const L1='9F86D081884C7D659A2F', L2='EAA0C55AD015A3BF4F1B';
const boxP=A.p(tC-0.1,0.45,'snapSettle');
if(boxP>0){
  const settle=A.p(tC,0.65,'cruise');
  const r2=A.rand(Math.floor(t*24)+3);
  const total=L1.length+L2.length;
  const scr=(str,base)=>{let s='';for(let i=0;i<str.length;i++){s+=((base+i)/total<settle*1.02)?str[i]:hexs[Math.floor(r2()*16)];}return s;};
  const s1=scr(L1,0), s2=scr(L2,L1.length);
  const hi=t>tHash;
  const hp=A.p(tHash,0.35,'popOver');
  const bump=hi?1+0.05*Math.sin(hp*Math.PI):1;
  const by=1460;
  A.with(()=>{
    A.rect(cx-400,by-100,800,200,{r:26,fill:'#03121a',stroke:hi?ac:'#5d8aa3',lw:hi?8:5,glow:hi?34:10});
    ctx.save();
    ctx.font=MONO;ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.fillStyle=hi?'#D9FBFF':'#9EEFFA';ctx.shadowColor=ac;ctx.shadowBlur=hi?26:14;
    if(ctx.letterSpacing!==undefined) ctx.letterSpacing='4px';
    ctx.fillText(s1,cx,by-30);
    ctx.fillText(s2,cx,by+42);
    ctx.restore();
  },{x:cx,y:by,scale:A.lerp(0.55,1,boxP)*bump,alpha:A.clamp(boxP*1.5)});
  if(hi){
    A.label('HASH',cx,by-100,{size:56,bg:ac,color:dark,scale:A.pop(tHash,0.45)});
    A.rings(cx,by,tHash,{count:2,speed:600,gap:0.12,maxR:480,color:ac,lw:4,alpha:0.45});
    A.flash(tHash,0.15,0.2);
    // entra en el servidor
    A.arrow(cx,by+104,cx,1604,{progress:A.p(tHash+0.12,0.25,'whip'),color:ac,lw:8,head:20});
  }
}
// ---------- CHECK EN SERVIDOR ----------
if(t>tHash+0.3){
  const ck=A.pop(tHash+0.3,0.35);
  A.with(()=>{
    A.circle(vx+270,vy-80,40,{fill:ac,glow:18});
    A.line([[vx+252,vy-80],[vx+266,vy-66],[vx+290,vy-94]],{stroke:dark,lw:10});
  },{x:vx+270,y:vy-80,scale:ck});
}

A.bg('#06120a','#020604');
const acc=A.accent||'#7CFC00', red='#FF4D6D';
const kHash=A.k('hash',0.333), kForm=A.k('fórmula',1.333), kConv=A.k('convierte',2.0), kCod=A.k('código',3.667), kLarg=A.k('larguísimo',4.0), kNo=A.k('no',4.667), kRev=A.k('revertir',5.667);
const PW_Y=465, MY=750;

// ---------- MÁQUINA (fórmula) ----------
const mS=A.pop(kForm-0.1,0.5);
const working=t>kConv+0.45&&t<kCod+0.35;
const shake=working?5:(t>kRev&&t<kRev+0.35?8:0);
const spin=t*0.6+A.clamp((t-kConv)/(kCod+0.4-kConv))*9;
function gear(cx,cy,r,ang,col){
  ctx.save();ctx.translate(cx,cy);ctx.rotate(ang);ctx.beginPath();
  const n=10;
  for(let i=0;i<=n*4;i++){const a=i/(n*4)*Math.PI*2;const rr=(Math.floor(i/2)%2)?r:r*0.8;const x=Math.cos(a)*rr,y=Math.sin(a)*rr;i?ctx.lineTo(x,y):ctx.moveTo(x,y);}
  ctx.closePath();ctx.fillStyle='#0f2a12';ctx.fill();ctx.lineWidth=4;ctx.strokeStyle=col;ctx.stroke();
  ctx.beginPath();ctx.arc(0,0,r*0.28,0,Math.PI*2);ctx.stroke();
  ctx.restore();
}
if(mS>0){
  A.with(()=>{
    ctx.beginPath();ctx.moveTo(430,615);ctx.lineTo(650,615);ctx.lineTo(600,655);ctx.lineTo(480,655);ctx.closePath();
    ctx.fillStyle='#0d1f10';ctx.fill();ctx.lineWidth=4;ctx.strokeStyle='#fff';ctx.stroke();
    A.rect(290,655,500,190,{r:28,fill:'#0b1a0d',stroke:'#ffffff',lw:5});
    A.lib&&A.lib.hatch&&A.lib.hatch(ctx,[[300,665],[780,665],[780,835],[300,835]],{angle:-0.6,spacing:22,width:1.5,color:'rgba(124,252,0,0.12)'});
    gear(440,MY,60,spin,acc);
    gear(560,MY,46,-spin*1.3+0.3,acc);
    gear(668,MY,56,spin*1.1,acc);
    A.rect(480,841,120,14,{r:6,fill:acc});
  },{x:540,y:MY,scale:mS,shake});
  A.label('FÓRMULA',540,578,{size:30,bg:acc,color:'#041004',scale:A.pop(kForm,0.45)});
}
if(working){
  A.particles(18,5,(i,r)=>{
    const ph=((t*1.6+r())%1);
    const a=r()*Math.PI*2, d=60+ph*220;
    A.circle(540+Math.cos(a)*d*1.3,MY+Math.sin(a)*d*0.6,5*(1-ph)+1,{fill:acc,alpha:1-ph});
  });
}

// ---------- CONTRASEÑA ----------
const pIn=A.pop(kHash-0.15,0.5);
const pDrop=A.p(kConv,0.7,'whip');
const pwY=A.lerp(PW_Y,690,pDrop);
const pwA=1-A.clamp((pDrop-0.6)/0.4);
if(pIn>0&&pwA>0){
  A.with(()=>{
    A.rect(340,pwY-50,400,100,{r:50,fill:'#0d1f10',stroke:'#ffffff',lw:5});
    A.text('gato123',540,pwY,{size:58,color:'#ffffff',weight:'800',align:'center'});
  },{x:540,y:pwY,scale:pIn*A.lerp(1,0.35,pDrop),alpha:pwA});
}

// ---------- HASH ----------
const hx='0123456789abcdef', rnd=A.rand(7);
let hs='';for(let i=0;i<64;i++)hs+=hx[Math.floor(rnd()*16)];
const hOut=A.p(kCod-0.1,0.55,'snapSettle');
const typeP=A.clamp((t-kCod)/(kLarg+0.7-kCod));
const nChars=Math.floor(typeP*64);
if(hOut>0){
  const hy=A.lerp(860,1010,hOut);
  A.arrow(540,858,540,A.lerp(862,915,hOut),{color:acc,lw:6,progress:hOut,alpha:hOut});
  A.with(()=>{
    A.rect(90,hy-90,900,180,{r:24,fill:'#071407',stroke:acc,lw:5,glow:20});
    ctx.save();ctx.font='700 46px monospace';ctx.textAlign='left';ctx.textBaseline='middle';
    const cuts=[0,22,43,64], cw=ctx.measureText('0').width;
    for(let L=0;L<3;L++){
      const a=cuts[L], b=cuts[L+1], len=b-a;
      const shown=hs.slice(a,Math.max(a,Math.min(nChars,b)));
      const x0=540-len*cw/2, y=hy-54+L*54;
      ctx.fillStyle=acc;ctx.fillText(shown,x0,y);
      if(nChars>=a&&nChars<b&&Math.floor(t*8)%2===0){ctx.fillStyle='#ffffff';ctx.fillRect(x0+shown.length*cw+2,y-22,cw*0.7,44);}
    }
    ctx.restore();
  },{x:540,y:hy,scale:A.lerp(0.4,1,hOut),alpha:hOut});
}
// contador sincronizado con el hash
const cS=A.pop(kCod,0.45);
if(cS>0){
  const done=nChars>=64;
  const bump=done?1+0.12*Math.max(0,1-(t-(kLarg+0.7))/0.3):1;
  A.with(()=>{
    A.text(String(nChars),470,1420,{size:110,color:done?acc:'#ffffff',weight:'900',align:'right'});
    A.text('caracteres',490,1420,{size:52,color:acc,weight:'700',align:'left'});
  },{x:540,y:1420,scale:cS*bump});
}

// ---------- INTENTO DE REVERTIR (lado izquierdo) ----------
const rp=A.p(kNo-0.05,0.5,'glide');
const XX=180, XY=800;
if(rp>0){
  // fantasma donde estaba la contraseña
  A.with(()=>{
    A.rect(340,PW_Y-50,400,100,{r:50,stroke:red,lw:4,alpha:0.8,dash:[14,12]});
