    ctx.restore();
  } else {
    A.circle(x, y, r, { fill: ac, alpha: alpha });
    const c = [];
    for (let i = 0; i <= 48; i++) { const a = i / 48 * Math.PI * 2; c.push([x + Math.cos(a) * r, y + Math.sin(a) * r]); }
    A.line(c, { stroke: WH, lw: 5, dash: [14, 12], alpha: Math.min(1, alpha * 2) });
  }
  const R = A.rand(7);
  for (let i = 0; i < 14; i++) {
    const a = R() * 6.28, d = Math.sqrt(R()) * r * 0.75;
    A.circle(x + Math.cos(a) * d, y + Math.sin(a) * d, r * 0.025 + 1, { fill: '#a8401a', alpha: alpha * 0.7 });
  }
  ctx.save(); ctx.globalAlpha = alpha * 0.85; ctx.fillStyle = WH; ctx.beginPath();
