  // tallo + hoja
  A.line([[x, y - r + 4], [x + 3, y - r - 12]], { stroke: '#6b3b1a', lw: 7, alpha });
  ctx.save(); ctx.globalAlpha = alpha; ctx.fillStyle = LEAF; ctx.strokeStyle = WH; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.ellipse(x + r * 0.3, y - r - 4, r * 0.3, r * 0.12, -0.35, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(x + 4, y - r + 2); ctx.lineTo(x + r * 0.55, y - r - 12); ctx.stroke(); ctx.restore();
}

