        ctx.fillStyle = Y; ctx.shadowColor = Y; ctx.shadowBlur = 30 + 10 * Math.sin(t * 8); ctx.fill(); ctx.shadowBlur = 0;
        ctx.lineJoin = 'round'; ctx.lineWidth = 8; ctx.strokeStyle = DARK; ctx.stroke();
        A.text('!', wx, wy + 70, { size: 170, color: DARK, weight: 900, align: 'center' });
      }, { x: wx, y: wy, scale: pW, rot: -0.12 + Math.sin(t * 6) * 0.03 });
    }
  }
  ctx.restore();

  // ---------- BASE DE DATOS ----------
  const pLn = A.p(kSig + 0.15, 0.5, 'glide');
  if (pLn > 0) A.line([[540, 1100], [540, 1380]], { stroke: Y, lw: 5, dash: [14, 14], progress: pLn, alpha: 0.5 });
  const pDB = A.pop(kSig + 0.45, 0.5);
  if (pDB > 0) {
    A.with(() => {
      const cx = 540, top = 1410, bot = 1680, rx = 210, ry = 40;
      ctx.fillStyle = '#16264C';
      ctx.fillRect(cx - rx, top, rx * 2, bot - top);
      ctx.beginPath(); ctx.ellipse(cx, bot, rx, ry, 0, 0, Math.PI); ctx.fill();
      try { A.lib.hatch(ctx, [[cx + rx - 70, top], [cx + rx, top], [cx + rx, bot], [cx + rx - 70, bot]], { angle: 60, spacing: 12, width: 1.5, color: 'rgba(255,255,255,0.15)' }); } catch (e) {}
      ctx.strokeStyle = WH; ctx.lineWidth = 4;
      ctx.beginPath(); ctx.moveTo(cx - rx, top); ctx.lineTo(cx - rx, bot); ctx.ellipse(cx, bot, rx, ry, 0, Math.PI, 0, true); ctx.lineTo(cx + rx, top); ctx.stroke();
      [1500, 1590].forEach(yy => { ctx.beginPath(); ctx.ellipse(cx, yy, rx, ry, 0, 0, Math.PI); ctx.strokeStyle = 'rgba(244,247,255,0.35)'; ctx.lineWidth = 3; ctx.stroke(); });
      ctx.beginPath(); ctx.ellipse(cx, top, rx, ry, 0, 0, Math.PI * 2); ctx.fillStyle = '#24396E'; ctx.fill(); ctx.strokeStyle = WH; ctx.lineWidth = 4; ctx.stroke();
      const rows = [['ana', 'Gato1234'], ['luis', 'Sol2020'], ['eva', 'Rosa99']];
      rows.forEach((r, i) => {
        const pr = A.p(kGua - 0.1 + i * 0.12, 0.35, 'softLand');
        if (pr <= 0) return;
        const yy = 1485 + i * 88;
        A.text(r[0], cx - 170 + (1 - pr) * -30, yy, { size: 32, color: WH, weight: 700, align: 'left', alpha: 0.75 * pr });
        A.text(r[1], cx + 170, yy, { size: 38, color: i === 0 && t > kSin ? R : Y, weight: 900, align: 'right', alpha: pr });
      });
    }, { x: 540, y: 1540, scale: pDB });
  }

  // Candado abierto
  const pK = A.pop(kSin, 0.45);
  if (pK > 0) {
    const kx = 860, ky = 1500;
    A.rings(kx, ky, kSin, { count: 2, maxR: 170, color: R, lw: 5 });
    A.with(() => {
      const lift = 34 + Math.sin(t * 10) * 4;
      ctx.beginPath(); ctx.lineWidth = 16; ctx.strokeStyle = WH; ctx.lineCap = 'round';
      ctx.arc(kx - 30, ky - 30 - lift, 40, Math.PI, 0); ctx.lineTo(kx + 10, ky - 30 - lift + 20);
      ctx.moveTo(kx - 70, ky - 30 - lift); ctx.lineTo(kx - 70, ky - 20);
      ctx.stroke();
      A.rect(kx - 70, ky - 25, 140, 110, { r: 16, fill: R, glow: 25 });
      A.circle(kx, ky + 22, 13, { fill: DARK });
      A.rect(kx - 5, ky + 26, 10, 30, { r: 4, fill: DARK });
    }, { x: kx, y: ky, scale: pK, rot: 0.15 });
  }

  // Sello
  const pS = A.pop(kPro, 0.4);
  if (pS > 0) {
    A.with(() => {
      A.label('SIN PROTECCIÓN', 540, 1705, { size: 52, bg: R, color: WH });
    }, { x: 540, y: 1705, scale: A.lerp(1.8, 1, A.clamp(pS)) * pS, rot: -0.08 });
  }
}, { shake: shake });

A.flash(kDes, 0.3, 0.35);
A.flash(kPro, 0.2, 0.15);

const W=A.W, acc=A.accent;
A.bg('#0B1430','#050914',true);
const cx=540, cy=760;
const kSig=A.k('Síguenos',0), kEnt=A.k('entender',0.667), kMun=A.k('mundo',2.0), kQue=A.k('¿Qué',2.333), kDud=A.k('duda',3.0), kInt=A.k('internet',3.667);

// 1) hash characters converge into a circle
const rnd=A.rand(7); const hex='0123456789abcdef';
const n=28; const chars=[]; for(let i=0;i<n;i++) chars.push(hex[Math.floor(rnd()*16)]);
const pc=A.p(kEnt-0.4,1.1,'glide');
const pg=A.p(kMun-0.5,0.7,'softLand');
const pq=A.p(kQue,0.5,'whip');
const hexAlpha=(1-pg)*A.clamp(t/0.25);
if(hexAlpha>0.01){
  for(let i=0;i<n;i++){
    const x0=90+i*(900/(n-1)), y0=cy+Math.sin(t*4+i*0.5)*8;
    const ang=i/n*Math.PI*2+t*1.2;
    const x1=cx+Math.cos(ang)*230, y1=cy+Math.sin(ang)*230;
    const x=A.lerp(x0,x1,pc), y=A.lerp(y0,y1,pc);
    A.text(chars[i],x,y,{size:44,color:i%5===0?acc:'#E8F0FF',weight:'700',align:'center',alpha:hexAlpha});
  }
}

// 2) globe
const gAlpha=pg*(1-pq);
if(gAlpha>0.01){
  const sc=A.lerp(1,0.17,pq);
  const gx=cx, gy=A.lerp(cy,1010,pq);
  A.with(()=>{
    const R=230;
    const pts=[];for(let a=0;a<=40;a++){const th=a/40*Math.PI*2;pts.push([gx+Math.cos(th)*R,gy+Math.sin(th)*R]);}
    A.lib.hatch(ctx,pts,{angle:-0.6,spacing:16,width:1.5,color:'rgba(255,212,0,0.18)'});
    A.circle(gx,gy,R,{stroke:acc,lw:6,glow:20});
    const rot=(t*0.6)%1;
    for(let m=0;m<4;m++){
      const ph=((m/4+rot)%1);
      const rx=Math.abs(Math.cos(ph*Math.PI))*R;
      ctx.save();ctx.strokeStyle='#E8F0FF';ctx.globalAlpha=0.7;ctx.lineWidth=3;
      ctx.beginPath();ctx.ellipse(gx,gy,Math.max(rx,1),R,0,0,Math.PI*2);ctx.stroke();ctx.restore();
    }
    [-0.5,0,0.5].forEach(f=>{const yy=gy+f*R*1.4;const hw=Math.sqrt(Math.max(0,R*R-(f*R*1.4)**2));
      A.line([[gx-hw,yy],[gx+hw,yy]],{stroke:'#E8F0FF',lw:3,alpha:0.6,progress:pg});});
  },{x:gx,y:gy,scale:A.pop(kMun-0.3,0.5)*sc,alpha:gAlpha});
  if(pq<0.01) A.rings(cx,cy,kMun,{count:2,maxR:380,color:acc,lw:4,alpha:0.6});
}

// 3) question mark
if(t>=kQue){
  const s=A.pop(kQue+0.15,0.5);
  A.with(()=>{
    // hook
    A.lib.inkPath(ctx,[[420,640],[440,540],[540,500],[640,540],[660,640],[600,730],[540,790],[540,900]],{width:44,color:acc,draw:A.p(kQue,0.55,'snapSettle')});
  },{x:540,y:760,scale:s,shake:A.clamp(1-(t-kQue-0.3)/0.3)*10*(t>kQue+0.3?1:0)});
  A.circle(540,1010,40,{fill:acc,glow:30});
  A.flash(kQue+0.3,0.25,0.25);
  A.rings(540,760,kQue+0.3,{count:2,maxR:420,color:acc,lw:3,alpha:0.5});
}

// 4) other doubts
const qs=[['¿WiFi?',230,560,0],['¿VPN?',860,620,0.15],['¿Cookies?',260,980,0.3],['¿Nube?',850,960,0.45]];
qs.forEach(([s,x,y,d])=>{
